import{_ as e,c as a,o as t,ae as l}from"./chunks/framework.BrQRMotl.js";const p=JSON.parse('{"title":"平滑移动指令","description":"","frontmatter":{},"headers":[],"relativePath":"zh/manual/smooth_move.md","filePath":"zh/manual/smooth_move.md"}'),i={name:"zh/manual/smooth_move.md"};function s(c,o,n,d,r,h){return t(),a("div",null,[...o[0]||(o[0]=[l('<h1 id="平滑移动指令" tabindex="-1">平滑移动指令 <a class="header-anchor" href="#平滑移动指令" aria-label="Permalink to &quot;平滑移动指令&quot;">​</a></h1><p><code>/smoothmove</code> 是一个强大的实用指令，允许管理员让玩家或实体以平滑的速度、指定的方向进行移动。</p><h2 id="指令语法" tabindex="-1">指令语法 <a class="header-anchor" href="#指令语法" aria-label="Permalink to &quot;指令语法&quot;">​</a></h2><h3 id="_1-开始移动" tabindex="-1">1. 开始移动 <a class="header-anchor" href="#_1-开始移动" aria-label="Permalink to &quot;1. 开始移动&quot;">​</a></h3><div class="language-mcfunction vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mcfunction</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/smoothmove &lt;目标&gt; &lt;方向&gt; &lt;速度&gt; [时长]</span></span></code></pre></div><ul><li><strong>目标</strong>: 要移动的实体选择器（如 <code>@s</code>, <code>@p</code>, <code>@e[type=zombie]</code>）。</li><li><strong>方向</strong>: <ul><li><code>north</code>, <code>south</code>, <code>east</code>, <code>west</code>: 东南西北。</li><li><code>x</code>, <code>-x</code>, <code>y</code>, <code>-y</code>, <code>z</code>, <code>-z</code>: 坐标轴方向。</li><li><code>forward</code>: 玩家当前水平面对的方向。</li><li><code>look</code>: 玩家当前视线指向的精确方向（包含垂直分量）。</li></ul></li><li><strong>速度</strong>: 每一刻 (Tick) 移动的距离（1 代表 20格/秒，TPS=20）。</li><li><strong>时长</strong> (可选): 移动持续的 Tick 数。如果不填，则会一直按此速度移动下去。</li></ul><h3 id="_2-停止移动" tabindex="-1">2. 停止移动 <a class="header-anchor" href="#_2-停止移动" aria-label="Permalink to &quot;2. 停止移动&quot;">​</a></h3><div class="language-mcfunction vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mcfunction</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/smoothmove stop &lt;目标&gt;</span></span></code></pre></div><ul><li>立即强制停止指定实体的平滑移动状态。</li></ul><h2 id="核心特性" tabindex="-1">核心特性 <a class="header-anchor" href="#核心特性" aria-label="Permalink to &quot;核心特性&quot;">​</a></h2><ol><li><strong>穿墙</strong>: <ul><li>在平滑移动期间，实体将进入 <code>noClip</code> 状态（类似于观察者模式），可以穿过方块而不会被卡住或发生碰撞。</li></ul></li><li><strong>服务器控制</strong>: <ul><li>移动轨迹由服务器强行同步，这消除了客户端因为网络延迟或碰撞检测而产生的抖动（Rubberbanding）。</li></ul></li><li><strong>安全保障</strong>: <ul><li>移动期间实体的掉落伤害将被重置为 0，防止长距离移动后落地暴毙。</li><li>移动结束或停止后，实体将恢复正常的碰撞检测。</li></ul></li></ol>',11)])])}const m=e(i,[["render",s]]);export{p as __pageData,m as default};
